		if err != nil {
			t.Fatal(err)
		}
		return fset, f
	}
	for name, src := range map[string]string{
		"field":    "package v\ntype S struct{ Spinner bool }\n",
		"selector": "package v\nfunc f(s S) bool { return s.Spinner }\n",
